import os
import pty
import select
import threading
import time


class HeadlessTerminal:
    def __init__(self, user='root'):
        pid, master = pty.fork()
        if pid == 0:
            os.environ['USER'] = user
            os.environ['HOME'] = os.path.expanduser('~' + user)
            os.execv('/bin/bash', ['bash', '-l', '-i'])

        self.master = master
        self.pid = pid
        self._drain = threading.Thread(target=self._read, daemon=True)
        self._drain.start()

    def _read(self):
        while True:
            try:
                r, _, _ = select.select([self.master], [], [])
                if self.master in r:
                    os.read(self.master, 65536)
            except OSError:
                break

    def send_keystrokes(self, keystrokes: str, wait_sec: float = 0.0) -> None:
        if keystrokes:
            os.write(self.master, keystrokes.encode('utf-8'))
        if wait_sec:
            time.sleep(wait_sec)
EOF
